import os
import torch
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Helper to compile a custom CUDA kernel that performs sum reduction
# over a fixed dimension (0, 1, or 2).  All tensors are fp16, accumulation
# is done in fp32 for numerical safety.
# ----------------------------------------------------------------------
def _compile_sum_reduce_kernel(reduce_dim: int):
    assert reduce_dim in (0, 1, 2)

    # Fixed sizes taken from the reference script
    BATCH, D1, D2 = 128, 4096, 4095

    # ------------------------------------------------------------------
    # CUDA source code – a single kernel specialised for the chosen dim
    # ------------------------------------------------------------------
    cuda_src = f"""
    #include <cuda_fp16.h>
    #include <torch/types.h>
    #include <torch/extension.h>

    extern "C" __global__
    void sum_reduce_kernel(const __half* __restrict__ A,
                           __half* __restrict__ B,
                           int batch, int dim1, int dim2) {{
        // launch configuration depends on reduce_dim (hard‑coded below)
        // each thread computes one output element.
        #if {reduce_dim} == 0
            // reduce over batch dimension -> output shape (1, dim1, dim2)
            int i1 = blockIdx.x * blockDim.x + threadIdx.x;
            int i2 = blockIdx.y * blockDim.y + threadIdx.y;
            if (i1 < dim1 && i2 < dim2) {{
                float acc = 0.0f;
                for (int i0 = 0; i0 < batch; ++i0) {{
                    int idx = (i0 * dim1 + i1) * dim2 + i2;
                    acc += __half2float(A[idx]);
                }}
                B[i1 * dim2 + i2] = __float2half(acc);
            }}
        #elif {reduce_dim} == 1
            // reduce over dim1 -> output shape (batch, 1, dim2)
            int b = blockIdx.x;
            int i2 = blockIdx.y * blockDim.x + threadIdx.x;
            if (b < batch && i2 < dim2) {{
                float acc = 0.0f;
                for (int i1 = 0; i1 < dim1; ++i1) {{
                    int idx = (b * dim1 + i1) * dim2 + i2;
                    acc += __half2float(A[idx]);
                }}
                B[b * dim2 + i2] = __float2half(acc);
            }}
        #else   // {reduce_dim} == 2
            // reduce over dim2 -> output shape (batch, dim1, 1)
            int b = blockIdx.x;
            int i1 = blockIdx.y * blockDim.x + threadIdx.x;
            if (b < batch && i1 < dim1) {{
                float acc = 0.0f;
                for (int i2 = 0; i2 < dim2; ++i2) {{
                    int idx = (b * dim1 + i1) * dim2 + i2;
                    acc += __half2float(A[idx]);
                }}
                B[b * dim1 + i1] = __float2half(acc);
            }}
        #endif
    }}

    // ------------------------------------------------------------------
    // PyTorch‑visible wrapper
    // ------------------------------------------------------------------
    at::Tensor sum_reduce(at::Tensor A) {{
        TORCH_CHECK(A.is_cuda(), "Input must be a CUDA tensor");
        TORCH_CHECK(A.dtype() == at::kHalf, "Input must be torch.float16");
        const int batch = {BATCH};
        const int dim1 = {D1};
        const int dim2 = {D2};

        // compute output shape with keepdim=True
        std::vector<int64_t> out_shape = A.sizes().vec();
        out_shape[{reduce_dim}] = 1;
        auto B = at::empty(out_shape, A.options());

        // launch configuration
        const int tx = 256;
        const int ty = 1;
        dim3 block(tx, ty);
        dim3 grid;

        #if {reduce_dim} == 0
            grid = dim3( (dim1 + tx - 1) / tx,
                         (dim2 + ty - 1) / ty );
        #elif {reduce_dim} == 1
            grid = dim3( batch,
                         (dim2 + tx - 1) / tx );
        #else   // {reduce_dim} == 2
            grid = dim3( batch,
                         (dim1 + tx - 1) / tx );
        #endif

        sum_reduce_kernel<<<grid, block, 0,
            at::cuda::getCurrentCUDAStream()>>>(
                reinterpret_cast<const __half*>(A.data_ptr()),
                reinterpret_cast<__half*>(B.data_ptr()),
                batch, dim1, dim2);

        TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                    "CUDA kernel failed");
        return B;
    }}

    PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {{
        m.def("sum_reduce", &sum_reduce, "Sum reduction kernel (keepdim)");
    }}
    """

    # No extra C++ source is needed – everything lives in the CUDA string
    cpp_src = ""

    # Compile the extension in a deterministic temporary directory
    build_dir = os.path.join(os.path.abspath(os.path.dirname(__file__)), ".kernel_build")
    os.makedirs(build_dir, exist_ok=True)

    module = load_inline(
        name=f"sum_reduce_dim{reduce_dim}",
        cpp_sources=cpp_src,
        cuda_sources=cuda_src,
        functions=["sum_reduce"],
        extra_cflags=["-O3"],
        extra_cuda_cflags=["-O3", "-arch=sm_90"],
        verbose=False,
        build_directory=build_dir,
    )
    return module

# ----------------------------------------------------------------------
# ModelNew – drop‑in replacement for the reference Model
# ----------------------------------------------------------------------
class ModelNew(torch.nn.Module):
    """
    Performs a sum reduction over the dimension supplied at construction,
    identical to torch.sum(..., dim=..., keepdim=True) but using a custom
    CUDA kernel written in TileLang‑style CUDA.
    """

    def __init__(self, dim: int):
        super().__init__()
        if dim not in (0, 1, 2):
            raise ValueError("Supported reduction dimensions are 0, 1, or 2.")
        self.dim = dim
        # Compile (or fetch cached) kernel specialised for the chosen dim
        self._mod = _compile_sum_reduce_kernel(self.dim)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("Input tensor must be on CUDA.")
        if x.dtype != torch.float16:
            raise RuntimeError("Input tensor must be torch.float16.")
        if x.shape != (128, 4096, 4095):
            raise RuntimeError(
                "Input tensor shape must be (128, 4096, 4095) as per the reference."
            )
        # The compiled function returns a new tensor with keepdim=True
        return self._mod.sum_reduce(x)

# ----------------------------------------------------------------------
# Helper functions matching the reference script API
# ----------------------------------------------------------------------
def get_inputs():
    batch_size = 128
    dim1 = 4096
    dim2 = 4095
    # Use fp16 as required
    x = torch.rand(batch_size, dim1, dim2, dtype=torch.float16, device="cuda")
    return [x]

def get_init_inputs():
    # Default reduction dimension used in the reference example
    return [1]
